package io.postfx;

import java.io.InputStream;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Properties;

/** Version and git commit of this build (generated by Maven into build-info.properties and git.properties). */
public final class BuildInfo {
    private static final Properties BUILD = load("/io/postfx/build-info.properties");
    private static final Properties GIT = load("/io/postfx/git.properties");

    private BuildInfo() {}

    private static Properties load(String resource) {
        Properties p = new Properties();
        try (InputStream in = BuildInfo.class.getResourceAsStream(resource)) {
            if (in != null) p.load(in);
        } catch (Exception ignored) {
            // missing build metadata (e.g. running from an IDE without Maven): defaults are used
        }
        return p;
    }

    private static String get(Properties p, String key, String def) {
        String v = p.getProperty(key);
        return v == null || v.isBlank() || v.startsWith("${") ? def : v.strip();
    }

    public static String version() {
        return get(BUILD, "version", "dev");
    }

    public static String buildTime() {
        return get(BUILD, "build.time", "unknown");
    }

    public static String graalJsVersion() {
        return get(BUILD, "graaljs.version", "unknown");
    }

    public static String commit() {
        return get(GIT, "git.commit.id.abbrev", "unknown");
    }

    public static String commitFull() {
        return get(GIT, "git.commit.id", get(GIT, "git.commit.id.full", "unknown"));
    }

    public static String commitTime() {
        return get(GIT, "git.commit.time", "unknown");
    }

    public static String branch() {
        return get(GIT, "git.branch", "unknown");
    }

    public static boolean dirty() {
        return Boolean.parseBoolean(get(GIT, "git.dirty", "false"));
    }

    public static String tag() {
        return get(GIT, "git.closest.tag.name", "");
    }

    /** e.g. "0.5.0 (a1b2c3d)" or "0.5.0 (a1b2c3d, modified)". */
    public static String shortVersion() {
        String c = commit();
        if (c.equals("unknown")) return version();
        return version() + " (" + c + (dirty() ? ", modified" : "") + ")";
    }

    /** All build and runtime details, in display order. */
    public static Map<String, String> details() {
        Map<String, String> m = new LinkedHashMap<>();
        m.put("Version", version());
        m.put("Commit", commit().equals("unknown") ? "unknown (not built from a git checkout)" : commitFull() + (dirty() ? "  (uncommitted changes)" : ""));
        // CI builds of a tag are detached: the "branch" is then the commit id, which is not worth showing
        if (!branch().equals(commitFull()) && !branch().equals("unknown") || commit().equals("unknown")) m.put("Branch", branch());
        if (!tag().isEmpty()) m.put("Tag", tag());
        m.put("Commit date", commitTime());
        m.put("Build date", buildTime());
        m.put("Java", System.getProperty("java.version") + " (" + System.getProperty("java.vendor") + ")");
        String fx = System.getProperty("javafx.runtime.version");
        if (fx != null) m.put("JavaFX", fx);
        m.put("OS", System.getProperty("os.name") + " " + System.getProperty("os.version") + " (" + System.getProperty("os.arch") + ")");
        return m;
    }

    public static String describe() {
        StringBuilder sb = new StringBuilder("PostFX ").append(shortVersion()).append('\n');
        details().forEach((k, v) -> sb.append(String.format("%-12s %s%n", k + ":", v)));
        return sb.toString();
    }
}
